"""本体模型：解析结果的只读视图。

模型内部以不可变集合保存数据，所有读取接口返回新的不可变序列，
不会修改已解析的数据，因此同一模型可重复读取且结果稳定。
"""

from __future__ import annotations

from typing import Iterator, Optional, Tuple

from .query import QueryResult, run_query


class Triple(tuple):
    """一条三元组 (subject, predicate, object)，按字典序可比较。"""

    __slots__ = ()

    def __new__(cls, subject: str, predicate: str, object_: str) -> "Triple":
        return super().__new__(cls, (subject, predicate, object_))

    @property
    def subject(self) -> str:
        return self[0]

    @property
    def predicate(self) -> str:
        return self[1]

    @property
    def object(self) -> str:
        return self[2]

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return f"Triple({self[0]!r}, {self[1]!r}, {self[2]!r})"


class DerivedTriple:
    """一条推理结论：三元组 + 来源规则 id。"""

    __slots__ = ("_triple", "_rule_id")

    def __init__(self, triple: Triple, rule_id) -> None:
        self._triple = triple
        self._rule_id = rule_id

    @property
    def triple(self) -> Triple:
        return self._triple

    @property
    def subject(self) -> str:
        return self._triple.subject

    @property
    def predicate(self) -> str:
        return self._triple.predicate

    @property
    def object(self) -> str:
        return self._triple.object

    @property
    def rule_id(self):
        return self._rule_id

    def __iter__(self) -> Iterator:
        return iter((self._triple, self._rule_id))

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, DerivedTriple)
            and self._triple == other._triple
            and self._rule_id == other._rule_id
        )

    def __hash__(self) -> int:
        return hash((self._triple, self._rule_id))

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return f"DerivedTriple({self._triple!r}, rule_id={self._rule_id!r})"


class OntologyModel:
    """解析与推理完成后的本体模型。

    - explicit_triples：显式三元组，按 (主语, 谓语, 宾语) 字典序排列。
    - derived_triples：推理结论，同样按字典序排列，每条带来源规则 id。
    - entails(s, p, o)：判断单条三元组是否被蕴含（显式或推理得出）。
    所有读取接口均返回新对象，不改变模型内部数据。
    """

    __slots__ = ("_explicit", "_derived", "_facts", "_source")

    def __init__(self, explicit, derived) -> None:
        # explicit / derived: dict[Triple, rule_id 或 None]
        self._explicit = frozenset(explicit)
        self._derived = frozenset(
            DerivedTriple(triple, rule_id) for triple, rule_id in derived.items()
        )
        self._facts = frozenset(explicit) | frozenset(derived)
        self._source = dict(derived)

    @property
    def explicit_triples(self) -> Tuple[Triple, ...]:
        """显式三元组，按字典序稳定排列。"""
        return tuple(sorted(self._explicit))

    @property
    def derived_triples(self) -> Tuple[DerivedTriple, ...]:
        """推理结论（含来源规则 id），按三元组字典序稳定排列。"""
        return tuple(sorted(self._derived, key=lambda d: (d.triple, str(d.rule_id))))

    @property
    def triples(self) -> Tuple[Triple, ...]:
        """全部三元组（显式 + 推理），按字典序稳定排列。"""
        return tuple(sorted(self._facts))

    def entails(self, subject: str, predicate: str, object_: str) -> bool:
        """判断 (subject, predicate, object_) 是否被当前模型蕴含。"""
        return Triple(subject, predicate, object_) in self._facts

    def source_rule(self, subject: str, predicate: str, object_: str) -> Optional[object]:
        """返回推理出该三元组的规则 id；显式或未知三元组返回 None。"""
        return self._source.get(Triple(subject, predicate, object_))

    def query(self, text: str) -> QueryResult:
        """执行 SPARQL 风格 SELECT 查询，在显式与推理三元组上匹配。

        例如 SELECT ?x ?y WHERE { ?x knows ?y . ?y likes ?z }；
        模式体中还可以出现 OPTIONAL { ... }（左连接，无匹配时块内变量未绑定）、
        FILTER ( 表达式 )（BOUND/!BOUND 与 =/!= 比较，多个 FILTER 逻辑与）
        以及 { ... } UNION { ... }（多个花括号分支取并集，分支内仅含三元组
        模式，连续 UNION 从左到右结合）。
        查询不修改模型，重复执行结果一致。词法或语法错误抛出 OntologyError。
        """
        return run_query(self, text)

"""OntologyEngine：解析 JSON 本体定义并做规则前向链推理。

输入约定（UTF-8 文本形式的 JSON）：

- 根对象必须包含 classes、properties、individuals、triples、rules 五个字段，
  可选包含 consistency 字段。
- classes / properties / individuals：字符串名称数组；名称在三个数组的并集内不得重复。
- triples：显式三元组数组，每项为 {"subject": ..., "predicate": ..., "object": ...}，
  三个值均为字符串，不允许变量；predicate 必须是已声明属性。
- rules：规则数组，每项为 {"id": ..., "if": [...], "then": [...]}；
  id 为字符串或整数且不得重复；if/then 为三元组模式数组，结构与 triples 相同，
  主语/宾语可以是以 "?" 开头的变量；then 中出现的变量必须在 if 中被绑定。
- consistency：可选对象，恰含 classMembershipPredicate、disjointClasses、
  functionalProperties 三个字段。

推理：对规则做前向链推理直至不动点。结论按 (主语, 谓语, 宾语) 字典序输出，
同一三元组被多条规则推出时保留最先推出它的规则 id；显式三元组优先于推理结论。

一致性诊断在结构校验与不动点推理完成后进行：同一个体同时属于一条
disjointClasses 约束中的两个类、或在一条 functionalProperties 约束的属性上
有两个不同取值，都抛出 InconsistencyError 且不返回模型。
"""

from __future__ import annotations

import json
from typing import Dict, List, Optional, Tuple

from .errors import InconsistencyError, OntologyError
from .model import OntologyModel, Triple

_ROOT_FIELDS = ("classes", "properties", "individuals", "triples", "rules")
_TRIPLE_KEYS = frozenset({"subject", "predicate", "object"})
_RULE_KEYS = frozenset({"id", "if", "then"})
_VARIABLE_PREFIX = "?"

_CONSISTENCY_KEYS = frozenset(
    {"classMembershipPredicate", "disjointClasses", "functionalProperties"}
)
_DISJOINT_KEYS = frozenset({"id", "classes"})
_FUNCTIONAL_KEYS = frozenset({"id", "property"})

# 冲突类型的稳定排序：disjointClasses 在 functionalProperties 之前。
_CONFLICT_DISJOINT = 0
_CONFLICT_FUNCTIONAL = 1


def _is_variable(value: str) -> bool:
    return value.startswith(_VARIABLE_PREFIX)


def _is_id(value) -> bool:
    """consistency 约束 id：非空字符串或整数（bool 不算）。"""
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    return isinstance(value, str) and bool(value)


class _RulePattern:
    """一条编译后的规则：id + if 模式列表 + then 模式列表。"""

    __slots__ = ("rule_id", "if_patterns", "then_patterns")

    def __init__(self, rule_id, if_patterns, then_patterns) -> None:
        self.rule_id = rule_id
        self.if_patterns = if_patterns  # List[Tuple[str, str, str]]
        self.then_patterns = then_patterns


class _DisjointConstraint:
    __slots__ = ("constraint_id", "classes")

    def __init__(self, constraint_id, classes: Tuple[str, ...]) -> None:
        self.constraint_id = constraint_id
        self.classes = tuple(classes)


class _FunctionalConstraint:
    __slots__ = ("constraint_id", "property")

    def __init__(self, constraint_id, property_: str) -> None:
        self.constraint_id = constraint_id
        self.property = property_


class _Consistency:
    __slots__ = ("membership_predicate", "disjoint", "functional")

    def __init__(self, membership_predicate, disjoint, functional) -> None:
        self.membership_predicate = membership_predicate
        self.disjoint = disjoint
        self.functional = functional


class OntologyEngine:
    """公开入口：解析本体定义文本，返回可重复读取的 OntologyModel。"""

    def parse(self, text) -> OntologyModel:
        """解析 UTF-8 文本形式的 JSON 本体定义并完成前向链推理。"""
        data = self._load_json(text)
        self._validate_root(data)
        classes, properties, individuals = self._collect_names(data)
        explicit = self._parse_explicit_triples(data["triples"], properties)
        rules = self._parse_rules(data["rules"], properties)
        consistency = self._parse_consistency(data, classes, properties)
        derived = self._forward_chain(explicit, rules)
        if consistency is not None:
            self._check_consistency(
                explicit, derived, consistency, classes, individuals
            )
        return OntologyModel(explicit, derived)

    def __call__(self, text) -> OntologyModel:
        return self.parse(text)

    # ---------- 解析与校验 ----------

    def _load_json(self, text):
        if isinstance(text, (bytes, bytearray)):
            try:
                text = bytes(text).decode("utf-8")
            except UnicodeDecodeError as exc:
                raise OntologyError(f"输入不是合法的 UTF-8 文本: {exc}") from exc
        if not isinstance(text, str):
            raise OntologyError(
                f"输入必须是 str 或 bytes 类型的 JSON 文本，收到 {type(text).__name__}"
            )
        try:
            return json.loads(text)
        except json.JSONDecodeError as exc:
            raise OntologyError(
                f"JSON 语法错误: 第 {exc.lineno} 行第 {exc.colno} 列: {exc.msg}"
            ) from exc

    def _validate_root(self, data) -> None:
        if not isinstance(data, dict):
            raise OntologyError(
                f"根节点必须是 JSON 对象，收到 {type(data).__name__}"
            )
        for field in _ROOT_FIELDS:
            if field not in data:
                raise OntologyError(f"根对象缺少必需字段 {field!r}")
            if not isinstance(data[field], list):
                raise OntologyError(
                    f"字段 {field!r} 必须是数组，收到 {type(data[field]).__name__}"
                )

    def _collect_names(self, data) -> Tuple[frozenset, frozenset, frozenset]:
        """校验 classes/properties/individuals，返回三个已声明名称集合。"""
        seen = {}
        for field in ("classes", "properties", "individuals"):
            for index, name in enumerate(data[field]):
                if not isinstance(name, str) or not name:
                    raise OntologyError(
                        f"字段 {field!r} 第 {index} 项必须是非空字符串，"
                        f"收到 {name!r}"
                    )
                if name in seen:
                    raise OntologyError(
                        f"名称 {name!r} 重复声明（出现在 {seen[name]!r} 与 {field!r}）"
                    )
                seen[name] = field
        return (
            frozenset(data["classes"]),
            frozenset(data["properties"]),
            frozenset(data["individuals"]),
        )

    def _check_triple_shape(self, item, where: str) -> dict:
        if not isinstance(item, dict):
            raise OntologyError(
                f"{where} 必须是包含 subject/predicate/object 的对象，"
                f"收到 {item!r}"
            )
        keys = set(item)
        if keys != _TRIPLE_KEYS:
            missing = _TRIPLE_KEYS - keys
            extra = keys - _TRIPLE_KEYS
            detail = []
            if missing:
                detail.append("缺少 " + ", ".join(sorted(missing)))
            if extra:
                detail.append("多出 " + ", ".join(sorted(extra)))
            raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")
        for key in ("subject", "predicate", "object"):
            if not isinstance(item[key], str) or not item[key]:
                raise OntologyError(
                    f"{where} 的 {key!r} 必须是非空字符串，收到 {item[key]!r}"
                )
        return item

    def _parse_explicit_triples(self, triples, properties) -> List[Triple]:
        result: List[Triple] = []
        seen = set()
        for index, item in enumerate(triples):
            where = f"triples[{index}]"
            self._check_triple_shape(item, where)
            s, p, o = item["subject"], item["predicate"], item["object"]
            for key, value in (("subject", s), ("predicate", p), ("object", o)):
                if _is_variable(value):
                    raise OntologyError(
                        f"{where} 的 {key!r} 不允许使用变量 {value!r}（显式三元组必须是基三元组）"
                    )
            if p not in properties:
                raise OntologyError(
                    f"{where} 引用了未声明的属性 {p!r}"
                )
            triple = Triple(s, p, o)
            if triple not in seen:
                seen.add(triple)
                result.append(triple)
        return result

    def _parse_rules(self, rules, properties) -> List[_RulePattern]:
        parsed: List[_RulePattern] = []
        seen_ids = set()
        for index, item in enumerate(rules):
            where = f"rules[{index}]"
            if not isinstance(item, dict):
                raise OntologyError(
                    f"{where} 必须是包含 id/if/then 的对象，收到 {item!r}"
                )
            keys = set(item)
            if keys != _RULE_KEYS:
                missing = _RULE_KEYS - keys
                extra = keys - _RULE_KEYS
                detail = []
                if missing:
                    detail.append("缺少 " + ", ".join(sorted(missing)))
                if extra:
                    detail.append("多出 " + ", ".join(sorted(extra)))
                raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")

            rule_id = item["id"]
            if isinstance(rule_id, bool) or not isinstance(rule_id, (str, int)):
                raise OntologyError(
                    f"{where} 的 id 必须是字符串或整数，收到 {rule_id!r}"
                )
            if isinstance(rule_id, str) and not rule_id:
                raise OntologyError(f"{where} 的 id 不能为空字符串")
            if rule_id in seen_ids:
                raise OntologyError(f"规则 id {rule_id!r} 重复（{where}）")
            seen_ids.add(rule_id)
            where = f"规则 {rule_id!r}"

            for field in ("if", "then"):
                if not isinstance(item[field], list):
                    raise OntologyError(
                        f"{where} 的 {field!r} 必须是三元组数组，"
                        f"收到 {type(item[field]).__name__}"
                    )

            if_patterns = self._parse_patterns(item["if"], properties, where, "if")
            then_patterns = self._parse_patterns(item["then"], properties, where, "then")

            bound = set()
            for s, _, o in if_patterns:
                if _is_variable(s):
                    bound.add(s)
                if _is_variable(o):
                    bound.add(o)
            for pos, (s, _, o) in enumerate(then_patterns):
                for key, value in (("subject", s), ("object", o)):
                    if _is_variable(value) and value not in bound:
                        raise OntologyError(
                            f"{where} 的 then[{pos}] 中变量 {value!r} 未在 if 中绑定"
                        )
            parsed.append(_RulePattern(rule_id, if_patterns, then_patterns))
        return parsed

    def _parse_patterns(self, patterns, properties, where: str, field: str):
        result = []
        for pos, item in enumerate(patterns):
            loc = f"{where} 的 {field}[{pos}]"
            self._check_triple_shape(item, loc)
            s, p, o = item["subject"], item["predicate"], item["object"]
            if _is_variable(p):
                raise OntologyError(
                    f"{loc} 的谓语不允许是变量 {p!r}（谓语只能是已声明属性）"
                )
            if p not in properties:
                raise OntologyError(f"{loc} 引用了未声明的属性 {p!r}")
            result.append((s, p, o))
        return result

    # ---------- consistency 结构校验 ----------

    def _parse_consistency(self, data, classes: frozenset, properties: frozenset):
        if "consistency" not in data:
            return None
        root = data["consistency"]
        if not isinstance(root, dict):
            raise OntologyError(
                "字段 'consistency' 必须是对象，"
                f"收到 {type(root).__name__}"
            )
        keys = set(root)
        if keys != _CONSISTENCY_KEYS:
            missing = _CONSISTENCY_KEYS - keys
            extra = keys - _CONSISTENCY_KEYS
            detail = []
            if missing:
                detail.append("缺少 " + ", ".join(sorted(missing)))
            if extra:
                detail.append("多出 " + ", ".join(sorted(extra)))
            raise OntologyError(f"consistency 结构不合法（{'; '.join(detail)}）")

        predicate = root["classMembershipPredicate"]
        if not isinstance(predicate, str) or not predicate:
            raise OntologyError(
                "consistency['classMembershipPredicate'] 必须是非空字符串，"
                f"收到 {predicate!r}"
            )
        if predicate not in properties:
            raise OntologyError(
                "consistency['classMembershipPredicate'] 引用了未声明的属性 "
                f"{predicate!r}"
            )

        seen_ids = {}
        disjoint = self._parse_disjoint(root["disjointClasses"], classes, seen_ids)
        functional = self._parse_functional(
            root["functionalProperties"], properties, seen_ids
        )
        return _Consistency(predicate, disjoint, functional)

    def _claim_constraint_id(self, constraint_id, where: str, seen_ids: dict) -> None:
        if not _is_id(constraint_id):
            raise OntologyError(
                f"{where}['id'] 必须是非空字符串或整数，收到 {constraint_id!r}"
            )
        if constraint_id in seen_ids:
            raise OntologyError(
                f"consistency 约束 id {constraint_id!r} 重复"
                f"（{seen_ids[constraint_id]} 与 {where}）"
            )
        seen_ids[constraint_id] = where

    def _parse_disjoint(self, items, classes: frozenset, seen_ids: dict):
        if not isinstance(items, list):
            raise OntologyError(
                "consistency['disjointClasses'] 必须是对象数组，"
                f"收到 {type(items).__name__}"
            )
        result = []
        for index, item in enumerate(items):
            where = f"consistency['disjointClasses'][{index}]"
            if not isinstance(item, dict):
                raise OntologyError(
                    f"{where} 必须是包含 id/classes 的对象，收到 {item!r}"
                )
            keys = set(item)
            if keys != _DISJOINT_KEYS:
                missing = _DISJOINT_KEYS - keys
                extra = keys - _DISJOINT_KEYS
                detail = []
                if missing:
                    detail.append("缺少 " + ", ".join(sorted(missing)))
                if extra:
                    detail.append("多出 " + ", ".join(sorted(extra)))
                raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")

            self._claim_constraint_id(item["id"], where, seen_ids)

            names = item["classes"]
            if not isinstance(names, list):
                raise OntologyError(
                    f"{where}['classes'] 必须是字符串数组，"
                    f"收到 {type(names).__name__}"
                )
            for pos, name in enumerate(names):
                if not isinstance(name, str) or not name:
                    raise OntologyError(
                        f"{where}['classes'][{pos}] 必须是非空字符串，收到 {name!r}"
                    )
            if len(names) < 2:
                raise OntologyError(
                    f"{where}['classes'] 至少需要列出两个类，收到 {len(names)} 个"
                )
            local_seen = set()
            for name in names:
                if name in local_seen:
                    raise OntologyError(
                        f"{where}['classes'] 中类名 {name!r} 重复"
                    )
                local_seen.add(name)
            for name in names:
                if name not in classes:
                    raise OntologyError(
                        f"{where}['classes'] 引用了未声明的类 {name!r}"
                    )
            result.append(_DisjointConstraint(item["id"], names))
        return result

    def _parse_functional(self, items, properties: frozenset, seen_ids: dict):
        if not isinstance(items, list):
            raise OntologyError(
                "consistency['functionalProperties'] 必须是对象数组，"
                f"收到 {type(items).__name__}"
            )
        result = []
        for index, item in enumerate(items):
            where = f"consistency['functionalProperties'][{index}]"
            if not isinstance(item, dict):
                raise OntologyError(
                    f"{where} 必须是包含 id/property 的对象，收到 {item!r}"
                )
            keys = set(item)
            if keys != _FUNCTIONAL_KEYS:
                missing = _FUNCTIONAL_KEYS - keys
                extra = keys - _FUNCTIONAL_KEYS
                detail = []
                if missing:
                    detail.append("缺少 " + ", ".join(sorted(missing)))
                if extra:
                    detail.append("多出 " + ", ".join(sorted(extra)))
                raise OntologyError(f"{where} 结构不合法（{'; '.join(detail)}）")

            self._claim_constraint_id(item["id"], where, seen_ids)

            property_ = item["property"]
            if not isinstance(property_, str) or not property_:
                raise OntologyError(
                    f"{where}['property'] 必须是非空字符串，收到 {property_!r}"
                )
            if property_ not in properties:
                raise OntologyError(
                    f"{where}['property'] 引用了未声明的属性 {property_!r}"
                )
            result.append(_FunctionalConstraint(item["id"], property_))
        return result

    # ---------- 前向链推理 ----------

    def _forward_chain(self, explicit: List[Triple], rules: List[_RulePattern]) -> Dict[Triple, object]:
        """返回 dict[Triple, rule_id]：仅包含推理结论（不含显式三元组）。"""
        facts: Dict[Triple, Optional[object]] = {t: None for t in explicit}
        while True:
            changed = False
            # 每轮按排序后的事实列表匹配，保证绑定枚举顺序确定。
            fact_list = sorted(facts)
            for rule in rules:
                for binding in self._match(rule.if_patterns, fact_list):
                    for pattern in rule.then_patterns:
                        triple = Triple(
                            binding.get(pattern[0], pattern[0]),
                            pattern[1],
                            binding.get(pattern[2], pattern[2]),
                        )
                        if triple not in facts:
                            facts[triple] = rule.rule_id
                            changed = True
            if not changed:
                break
        return {t: rid for t, rid in facts.items() if rid is not None}

    def _match(self, patterns, fact_list) -> List[Dict[str, str]]:
        """对 if 模式按序做连接匹配，返回所有满足的变量绑定。"""
        bindings: List[Dict[str, str]] = [{}]
        for s, p, o in patterns:
            next_bindings: List[Dict[str, str]] = []
            for binding in bindings:
                for fact in fact_list:
                    if fact.predicate != p:
                        continue
                    if _is_variable(s):
                        if s in binding and fact.subject != binding[s]:
                            continue
                    elif fact.subject != s:
                        continue
                    extended = dict(binding)
                    if _is_variable(s):
                        extended[s] = fact.subject
                    # 宾语变量需与同一模式内已绑定的主语变量保持一致（如 (?x, p, ?x)）。
                    if _is_variable(o):
                        if o in extended and fact.object != extended[o]:
                            continue
                    elif fact.object != o:
                        continue
                    if _is_variable(o):
                        extended[o] = fact.object
                    next_bindings.append(extended)
            bindings = next_bindings
            if not bindings:
                break
        return bindings

    # ---------- 一致性诊断 ----------

    def _check_consistency(
        self,
        explicit: List[Triple],
        derived: Dict[Triple, object],
        consistency: _Consistency,
        classes: frozenset,
        individuals: frozenset,
    ) -> None:
        # 全部事实的来源表：显式事实为 None，推理结论为来源规则 id。
        fact_source: Dict[Triple, Optional[object]] = {t: None for t in explicit}
        fact_source.update(derived)

        membership = self._membership_facts(
            fact_source, consistency.membership_predicate, classes, individuals
        )
        conflicts = []
        conflicts.extend(
            self._disjoint_conflicts(membership, consistency.disjoint)
        )
        conflicts.extend(
            self._functional_conflicts(fact_source, consistency.functional)
        )
        if not conflicts:
            return

        # 按约束 id 的字符串表示、冲突类型、subject、冲突条目字典序排列。
        conflicts.sort(key=lambda c: c[0])
        lines = [f"本体一致性诊断发现 {len(conflicts)} 处冲突："]
        lines.extend(c[1] for c in conflicts)
        raise InconsistencyError("\n".join(lines))

    def _membership_facts(
        self,
        fact_source: Dict[Triple, Optional[object]],
        predicate: str,
        classes: frozenset,
        individuals: frozenset,
    ) -> Dict[Tuple[str, str], Optional[object]]:
        """收集 {(subject, class): 来源}：仅保留已声明个体与已声明类上的类成员事实。"""
        membership: Dict[Tuple[str, str], Optional[object]] = {}
        for triple, source in fact_source.items():
            if triple.predicate != predicate:
                continue
            if triple.subject not in individuals:
                continue
            if triple.object not in classes:
                continue
            membership.setdefault((triple.subject, triple.object), source)
        return membership

    def _disjoint_conflicts(self, membership, constraints):
        conflicts = []
        for constraint in constraints:
            names = sorted(constraint.classes)
            holders: Dict[str, List[str]] = {}
            for subject, class_name in membership:
                if class_name in names:
                    holders.setdefault(subject, []).append(class_name)
            for subject, owned in holders.items():
                if len(owned) < 2:
                    continue
                owned_set = frozenset(owned)
                for pos, first in enumerate(names):
                    if first not in owned_set:
                        continue
                    for second in names[pos + 1 :]:
                        if second not in owned_set:
                            continue
                        src1 = membership[(subject, first)]
                        src2 = membership[(subject, second)]
                        message = (
                            f"[disjointClasses id={constraint.constraint_id!r}] "
                            f"个体 {subject!r} 同时属于互斥类 {first!r} 与 {second!r}："
                            f"{first!r} 为{self._describe_source(src1)}；"
                            f"{second!r} 为{self._describe_source(src2)}"
                        )
                        key = (
                            str(constraint.constraint_id),
                            _CONFLICT_DISJOINT,
                            subject,
                            first,
                            second,
                        )
                        conflicts.append((key, message))
        return conflicts

    def _functional_conflicts(self, fact_source: Dict[Triple, Optional[object]], constraints):
        conflicts = []
        for constraint in constraints:
            property_ = constraint.property
            # subject -> {object: 来源}
            by_subject: Dict[str, Dict[str, Optional[object]]] = {}
            for triple, source in fact_source.items():
                if triple.predicate != property_:
                    continue
                by_subject.setdefault(triple.subject, {}).setdefault(
                    triple.object, source
                )
            for subject, objects in by_subject.items():
                if len(objects) < 2:
                    continue
                ordered = sorted(objects)
                for pos, first in enumerate(ordered):
                    for second in ordered[pos + 1 :]:
                        src1 = objects[first]
                        src2 = objects[second]
                        message = (
                            f"[functionalProperties id={constraint.constraint_id!r}] "
                            f"个体 {subject!r} 在函数型属性 {property_!r} 上有两个不同取值 "
                            f"{first!r} 与 {second!r}："
                            f"{first!r} 为{self._describe_source(src1)}；"
                            f"{second!r} 为{self._describe_source(src2)}"
                        )
                        key = (
                            str(constraint.constraint_id),
                            _CONFLICT_FUNCTIONAL,
                            subject,
                            property_,
                            first,
                            second,
                        )
                        conflicts.append((key, message))
        return conflicts

    @staticmethod
    def _describe_source(source) -> str:
        if source is None:
            return "显式事实（explicit_triples）"
        return f"推理结论（derived_triples，source_rule={source!r}）"

import json
import unittest

from onto_reason import (
    InconsistencyError,
    OntologyEngine,
    OntologyError,
    QueryResult,
    Triple,
)


def make_doc(**overrides):
    doc = {
        "classes": ["Person"],
        "properties": ["knows", "likes", "friendOf"],
        "individuals": ["alice", "bob", "carol"],
        "triples": [
            {"subject": "alice", "predicate": "knows", "object": "bob"},
            {"subject": "bob", "predicate": "knows", "object": "carol"},
        ],
        "rules": [],
    }
    doc.update(overrides)
    return doc


def parse(doc):
    return OntologyEngine().parse(json.dumps(doc))


class ParseAndValidateTests(unittest.TestCase):
    def test_json_syntax_error(self):
        with self.assertRaises(OntologyError) as ctx:
            OntologyEngine().parse("{not json")
        self.assertIn("JSON", str(ctx.exception))

    def test_non_utf8_bytes(self):
        with self.assertRaises(OntologyError):
            OntologyEngine().parse(b"\xff\xfe{}")

    def test_utf8_bytes_accepted(self):
        model = OntologyEngine().parse(json.dumps(make_doc()).encode("utf-8"))
        self.assertEqual(len(model.explicit_triples), 2)

    def test_root_must_be_object(self):
        with self.assertRaises(OntologyError):
            OntologyEngine().parse("[1, 2]")

    def test_missing_root_field(self):
        doc = make_doc()
        del doc["rules"]
        with self.assertRaises(OntologyError) as ctx:
            parse(doc)
        self.assertIn("rules", str(ctx.exception))

    def test_root_field_wrong_type(self):
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(classes="Person"))
        self.assertIn("classes", str(ctx.exception))

    def test_duplicate_name_within_array(self):
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(individuals=["alice", "bob", "alice"]))
        self.assertIn("alice", str(ctx.exception))

    def test_duplicate_name_across_arrays(self):
        with self.assertRaises(OntologyError):
            parse(make_doc(classes=["Person"], individuals=["Person"]))

    def test_explicit_triple_bad_shape(self):
        bad = {"subject": "alice", "predicate": "knows"}
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(triples=[bad]))
        self.assertIn("triples[0]", str(ctx.exception))

    def test_explicit_triple_undeclared_property(self):
        bad = {"subject": "alice", "predicate": "hates", "object": "bob"}
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(triples=[bad]))
        self.assertIn("hates", str(ctx.exception))
        self.assertIn("triples[0]", str(ctx.exception))

    def test_explicit_triple_rejects_variable(self):
        bad = {"subject": "?x", "predicate": "knows", "object": "bob"}
        with self.assertRaises(OntologyError):
            parse(make_doc(triples=[bad]))

    def test_duplicate_rule_id(self):
        rule = {"id": "r1", "if": [], "then": []}
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(rules=[rule, rule]))
        self.assertIn("r1", str(ctx.exception))

    def test_rule_undeclared_property(self):
        rule = {
            "id": "r1",
            "if": [{"subject": "?x", "predicate": "hates", "object": "?y"}],
            "then": [],
        }
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(rules=[rule]))
        self.assertIn("r1", str(ctx.exception))
        self.assertIn("hates", str(ctx.exception))

    def test_rule_variable_predicate_rejected(self):
        rule = {
            "id": "r1",
            "if": [{"subject": "?x", "predicate": "?p", "object": "?y"}],
            "then": [],
        }
        with self.assertRaises(OntologyError):
            parse(make_doc(rules=[rule]))

    def test_unbound_then_variable(self):
        rule = {
            "id": "r-unbound",
            "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
            "then": [{"subject": "?x", "predicate": "likes", "object": "?z"}],
        }
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(rules=[rule]))
        self.assertIn("r-unbound", str(ctx.exception))
        self.assertIn("?z", str(ctx.exception))

    def test_rule_bad_shape(self):
        with self.assertRaises(OntologyError) as ctx:
            parse(make_doc(rules=[{"id": "r1", "if": []}]))
        self.assertIn("then", str(ctx.exception))


class InferenceTests(unittest.TestCase):
    def test_forward_chain_to_fixpoint(self):
        rule = {
            "id": "knows-likes",
            "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
            "then": [{"subject": "?x", "predicate": "likes", "object": "?y"}],
        }
        model = parse(make_doc(rules=[rule]))
        derived = model.derived_triples
        self.assertEqual(
            [d.triple for d in derived],
            [Triple("alice", "likes", "bob"), Triple("bob", "likes", "carol")],
        )
        self.assertTrue(all(d.rule_id == "knows-likes" for d in derived))

    def test_multi_hop_chain(self):
        # knows 传递闭包：alice -> bob -> carol 推出 alice -> carol
        rule = {
            "id": "knows-transitive",
            "if": [
                {"subject": "?x", "predicate": "knows", "object": "?y"},
                {"subject": "?y", "predicate": "knows", "object": "?z"},
            ],
            "then": [{"subject": "?x", "predicate": "knows", "object": "?z"}],
        }
        model = parse(make_doc(rules=[rule]))
        self.assertTrue(model.entails("alice", "knows", "carol"))
        self.assertEqual(
            model.source_rule("alice", "knows", "carol"), "knows-transitive"
        )

    def test_join_across_predicates(self):
        rule = {
            "id": "friend-of-friend",
            "if": [
                {"subject": "?x", "predicate": "knows", "object": "?y"},
                {"subject": "?y", "predicate": "likes", "object": "?z"},
            ],
            "then": [{"subject": "?x", "predicate": "friendOf", "object": "?z"}],
        }
        triples = make_doc()["triples"] + [
            {"subject": "bob", "predicate": "likes", "object": "carol"}
        ]
        model = parse(make_doc(triples=triples, rules=[rule]))
        self.assertTrue(model.entails("alice", "friendOf", "carol"))
        self.assertFalse(model.entails("carol", "friendOf", "alice"))

    def test_derived_does_not_duplicate_explicit(self):
        rule = {
            "id": "r1",
            "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
            "then": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
        }
        model = parse(make_doc(rules=[rule]))
        self.assertEqual(model.derived_triples, ())
        self.assertEqual(len(model.triples), 2)

    def test_same_conclusion_keeps_first_rule(self):
        rules = [
            {
                "id": "r-first",
                "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
                "then": [{"subject": "?x", "predicate": "likes", "object": "?y"}],
            },
            {
                "id": "r-second",
                "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
                "then": [{"subject": "?x", "predicate": "likes", "object": "?y"}],
            },
        ]
        model = parse(make_doc(rules=rules))
        self.assertEqual(len(model.derived_triples), 2)
        self.assertTrue(all(d.rule_id == "r-first" for d in model.derived_triples))

    def test_ground_then_with_empty_if(self):
        rule = {
            "id": "r-fact",
            "if": [],
            "then": [{"subject": "carol", "predicate": "likes", "object": "alice"}],
        }
        model = parse(make_doc(rules=[rule]))
        self.assertTrue(model.entails("carol", "likes", "alice"))

    def test_output_sorted_and_marked(self):
        model = parse(make_doc())
        self.assertEqual(
            list(model.explicit_triples),
            [Triple("alice", "knows", "bob"), Triple("bob", "knows", "carol")],
        )
        self.assertEqual(model.source_rule("alice", "knows", "bob"), None)

    def test_entails_false_for_unknown(self):
        model = parse(make_doc())
        self.assertFalse(model.entails("alice", "likes", "bob"))


class DeterminismAndImmutabilityTests(unittest.TestCase):
    def test_repeated_parse_same_result(self):
        doc = make_doc(
            rules=[
                {
                    "id": "r1",
                    "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
                    "then": [{"subject": "?x", "predicate": "likes", "object": "?y"}],
                }
            ]
        )
        text = json.dumps(doc)
        results = []
        for _ in range(3):
            model = OntologyEngine().parse(text)
            results.append(
                (model.explicit_triples, model.derived_triples, model.triples)
            )
        self.assertEqual(results[0], results[1])
        self.assertEqual(results[1], results[2])

    def test_reads_do_not_mutate_model(self):
        rule = {
            "id": "r1",
            "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
            "then": [{"subject": "?x", "predicate": "likes", "object": "?y"}],
        }
        model = parse(make_doc(rules=[rule]))
        before = (model.explicit_triples, model.derived_triples, model.triples)
        # 重复读取并尝试修改返回值
        model.explicit_triples
        derived = model.derived_triples
        model.entails("alice", "likes", "bob")
        model.source_rule("alice", "likes", "bob")
        self.assertIsNot(model.derived_triples, derived)
        after = (model.explicit_triples, model.derived_triples, model.triples)
        self.assertEqual(before, after)

    def test_self_variable_pattern(self):
        # (?x, knows, ?x) 只匹配主语与宾语相同的事实
        triples = [{"subject": "alice", "predicate": "knows", "object": "alice"}]
        rule = {
            "id": "self-like",
            "if": [{"subject": "?x", "predicate": "knows", "object": "?x"}],
            "then": [{"subject": "?x", "predicate": "likes", "object": "?x"}],
        }
        model = parse(make_doc(triples=triples, rules=[rule]))
        self.assertTrue(model.entails("alice", "likes", "alice"))
        self.assertFalse(model.entails("alice", "likes", "bob"))


def query_model():
    """带显式事实与推理结论的模型，供查询测试使用。"""
    rules = [
        {
            "id": "knows-likes",
            "if": [{"subject": "?x", "predicate": "knows", "object": "?y"}],
            "then": [{"subject": "?x", "predicate": "likes", "object": "?y"}],
        },
        {
            "id": "friend-of-friend",
            "if": [
                {"subject": "?x", "predicate": "knows", "object": "?y"},
                {"subject": "?y", "predicate": "likes", "object": "?z"},
            ],
            "then": [{"subject": "?x", "predicate": "friendOf", "object": "?z"}],
        },
    ]
    triples = make_doc()["triples"] + [
        {"subject": "bob", "predicate": "likes", "object": "carol"}
    ]
    return parse(make_doc(triples=triples, rules=rules))


class QueryTests(unittest.TestCase):
    def test_basic_join_returns_query_result(self):
        model = query_model()
        result = model.query(
            "SELECT ?x ?y WHERE { ?x knows ?y . ?y likes ?z }"
        )
        self.assertIsInstance(result, QueryResult)
        self.assertEqual(result.variables, ("?x", "?y"))
        self.assertEqual(result.rows, (("alice", "bob"),))

    def test_star_projection_first_appearance_order(self):
        model = query_model()
        result = model.query(
            "SELECT * WHERE { ?x knows ?y . ?y likes ?z }"
        )
        self.assertEqual(result.variables, ("?x", "?y", "?z"))
        self.assertEqual(result.rows, (("alice", "bob", "carol"),))

    def test_derived_triples_match_like_explicit(self):
        model = query_model()
        # alice likes bob 由规则 knows-likes 推出，应与显式事实一样命中
        result = model.query("SELECT ?x ?y WHERE { ?x likes ?y }")
        self.assertEqual(
            result.rows,
            (("alice", "bob"), ("bob", "carol")),
        )
        # 但 source_rule 仍只描述推理来源
        self.assertEqual(model.source_rule("alice", "likes", "bob"), "knows-likes")
        self.assertIsNone(model.source_rule("bob", "likes", "carol"))

    def test_constant_subject_and_object(self):
        model = query_model()
        self.assertEqual(
            model.query("SELECT ?y WHERE { alice knows ?y }").rows,
            (("bob",),),
        )
        self.assertEqual(
            model.query("SELECT ?y WHERE { ?y knows carol }").rows,
            (("bob",),),
        )
        self.assertEqual(
            model.query("SELECT * WHERE { alice knows carol }").rows,
            (),
        )

    def test_same_variable_bound_equal_within_pattern(self):
        model = query_model()
        self.assertEqual(
            model.query("SELECT ?x WHERE { ?x knows ?x }").rows, ()
        )

    def test_rows_deduped_and_sorted_by_projection(self):
        model = query_model()
        # 仅投影 ?y，?x 取值不同不产生重复行
        result = model.query("SELECT ?y WHERE { ?x knows ?y }")
        self.assertEqual(result.rows, (("bob",), ("carol",)))

    def test_no_match_returns_empty_rows(self):
        model = query_model()
        result = model.query("SELECT ?x WHERE { ?x knows nobody }")
        self.assertEqual(result.variables, ("?x",))
        self.assertEqual(result.rows, ())

    def test_ground_pattern_star_has_no_variables(self):
        model = query_model()
        hit = model.query("SELECT * WHERE { alice knows bob }")
        self.assertEqual(hit.variables, ())
        self.assertEqual(hit.rows, ((),))
        miss = model.query("SELECT * WHERE { alice knows nobody }")
        self.assertEqual(miss.rows, ())

    def test_trailing_dot_and_mixed_whitespace(self):
        model = query_model()
        result = model.query(
            "SELECT\t?x\nWHERE  {\n ?x knows ?y .\n}"
        )
        self.assertEqual(result.rows, (("alice",), ("bob",)))

    def test_json_string_literal_decoded_and_exact(self):
        doc = make_doc(
            triples=[
                {"subject": "alice", "predicate": "likes", "object": 'a"b  c'}
            ]
        )
        model = parse(doc)
        self.assertEqual(
            model.query(r'SELECT ?s WHERE { ?s likes "a\"b  c" }').rows,
            (("alice",),),
        )
        self.assertEqual(
            model.query(r'SELECT ?s WHERE { ?s likes "a\"b c" }').rows,
            (),
        )

    def test_unicode_variable_and_name(self):
        doc = make_doc(
            triples=[
                {"subject": "张三", "predicate": "knows", "object": "李四"}
            ]
        )
        model = OntologyEngine().parse(json.dumps(doc, ensure_ascii=False))
        result = model.query("SELECT ?人1 WHERE { ?人1 knows ?_y }")
        self.assertEqual(result.variables, ("?人1",))
        self.assertEqual(result.rows, (("张三",),))

    def test_pattern_order_only_affects_star_discovery(self):
        model = query_model()
        explicit_a = model.query(
            "SELECT ?x ?y ?z WHERE { ?x knows ?y . ?y likes ?z }"
        )
        explicit_b = model.query(
            "SELECT ?x ?y ?z WHERE { ?y likes ?z . ?x knows ?y }"
        )
        self.assertEqual(explicit_a.rows, explicit_b.rows)
        star_a = model.query(
            "SELECT * WHERE { ?x knows ?y . ?y likes ?z }"
        )
        star_b = model.query(
            "SELECT * WHERE { ?y likes ?z . ?x knows ?y }"
        )
        self.assertEqual(star_a.variables, ("?x", "?y", "?z"))
        self.assertEqual(star_b.variables, ("?y", "?z", "?x"))
        bindings_a = {tuple(sorted(zip(star_a.variables, r))) for r in star_a.rows}
        bindings_b = {tuple(sorted(zip(star_b.variables, r))) for r in star_b.rows}
        self.assertEqual(bindings_a, bindings_b)

    def test_repeated_execution_identical(self):
        model = query_model()
        text = "SELECT * WHERE { ?x knows ?y . ?y likes ?z }"
        first = model.query(text)
        for _ in range(3):
            again = model.query(text)
            self.assertEqual(again, first)
            self.assertIsNot(again.rows, first.rows)

    def test_rows_are_immutable_tuples(self):
        model = query_model()
        result = model.query("SELECT ?x WHERE { ?x knows ?y }")
        self.assertIsInstance(result.variables, tuple)
        self.assertIsInstance(result.rows, tuple)
        self.assertTrue(all(isinstance(row, tuple) for row in result.rows))
        with self.assertRaises(TypeError):
            result.rows[0] = ("x",)

    def test_query_does_not_mutate_model(self):
        model = query_model()
        before = (model.explicit_triples, model.derived_triples, model.triples)
        model.query("SELECT * WHERE { ?x knows ?y . ?y likes ?z }")
        after = (model.explicit_triples, model.derived_triples, model.triples)
        self.assertEqual(before, after)


class QuerySyntaxErrorTests(unittest.TestCase):
    def setUp(self):
        self.model = query_model()

    def assertQueryError(self, text, *fragments):
        with self.assertRaises(OntologyError) as ctx:
            self.model.query(text)
        message = str(ctx.exception)
        self.assertTrue(
            "字符位置" in message or "模式" in message,
            f"错误消息缺少字符位置或模式序号: {message}",
        )
        for fragment in fragments:
            self.assertIn(fragment, message)

    def test_lowercase_keywords_rejected(self):
        self.assertQueryError("select ?x WHERE { ?x knows ?y }")
        self.assertQueryError("SELECT ?x where { ?x knows ?y }")

    def test_missing_keywords_and_braces(self):
        self.assertQueryError("?x WHERE { ?x knows ?y }")
        self.assertQueryError("SELECT WHERE { ?x knows ?y }")
        self.assertQueryError("SELECT ?x { ?x knows ?y }")
        self.assertQueryError("SELECT ?x WHERE  ?x knows ?y }")
        self.assertQueryError("SELECT ?x WHERE { ?x knows ?y ")
        self.assertQueryError("SELECT ?x WHERE { ?x knows ?y } }")
        self.assertQueryError("")
        self.assertQueryError("SELECT")

    def test_duplicate_or_unknown_projection_variable(self):
        self.assertQueryError(
            "SELECT ?x ?x WHERE { ?x knows ?y }", "?x", "重复"
        )
        self.assertQueryError(
            "SELECT ?z WHERE { ?x knows ?y }", "?z", "未"
        )

    def test_empty_pattern_body(self):
        self.assertQueryError("SELECT * WHERE { }", "空")
        self.assertQueryError("SELECT * WHERE {  }", "空")

    def test_variable_predicate_rejected(self):
        self.assertQueryError("SELECT * WHERE { ?x ?p ?y }", "谓语", "模式 0")

    def test_unknown_statement_component(self):
        self.assertQueryError("SELECT ?x WHERE { ?x knows ?y } EXTRA")
        self.assertQueryError("SELECT * * WHERE { ?x knows ?y }")
        self.assertQueryError("SELECT . ?x WHERE { ?x knows ?y }")

    def test_pattern_arity_too_few_or_many(self):
        self.assertQueryError("SELECT * WHERE { ?x knows }", "模式 0", "项数不足")
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y likes ?z }", "项数过多"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . knows ?y }", "模式 1", "项数不足"
        )
        self.assertQueryError(
            "SELECT * WHERE { . ?x knows ?y }", "'.'"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . . ?y knows ?z }", "'.'"
        )

    def test_lexical_errors(self):
        self.assertQueryError("SELECT ? WHERE { ?x knows ?y }")
        self.assertQueryError('SELECT * WHERE { ?x likes "unclosed }')
        self.assertQueryError(r'SELECT * WHERE { ?x likes "bad\q" }')

    def test_non_str_input(self):
        with self.assertRaises(OntologyError) as ctx:
            self.model.query(123)
        self.assertIn("str", str(ctx.exception))


def optional_model():
    """带可选关联数据的模型：dave 没有 likes；只有 carol 有 email。"""
    doc = {
        "classes": ["Person"],
        "properties": ["knows", "likes", "email", "label"],
        "individuals": ["alice", "bob", "carol", "dave"],
        "triples": [
            {"subject": "alice", "predicate": "knows", "object": "bob"},
            {"subject": "bob", "predicate": "knows", "object": "carol"},
            {"subject": "carol", "predicate": "knows", "object": "dave"},
            {"subject": "bob", "predicate": "likes", "object": "tennis"},
            {"subject": "bob", "predicate": "likes", "object": "soccer"},
            {"subject": "carol", "predicate": "likes", "object": "music"},
            {"subject": "carol", "predicate": "email", "object": "c@example.com"},
        ],
        "rules": [],
    }
    return parse(doc)


class OptionalFilterTests(unittest.TestCase):
    def setUp(self):
        self.model = optional_model()

    def test_optional_extends_each_matching_binding(self):
        # bob 有两个 likes，左连接应扩展出两行；carol 一个；dave 无匹配保留 None
        result = self.model.query(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } }"
        )
        self.assertEqual(result.variables, ("?x", "?y", "?z"))
        self.assertEqual(
            result.rows,
            (
                ("alice", "bob", "soccer"),
                ("alice", "bob", "tennis"),
                ("bob", "carol", "music"),
                ("carol", "dave", None),
            ),
        )

    def test_optional_no_match_keeps_binding_once_with_none(self):
        result = self.model.query(
            "SELECT ?x ?e WHERE { ?x knows ?y . OPTIONAL { ?x email ?e } }"
        )
        self.assertEqual(
            result.rows,
            (("alice", None), ("bob", None), ("carol", "c@example.com")),
        )

    def test_optional_multiple_patterns_are_all_or_nothing(self):
        # label 三元组不存在，块内整组无任何匹配，两个块内变量均未绑定
        result = self.model.query(
            "SELECT * WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z . ?z label ?l } }"
        )
        self.assertEqual(result.variables, ("?x", "?y", "?z", "?l"))
        self.assertEqual(
            result.rows,
            (
                ("alice", "bob", None, None),
                ("bob", "carol", None, None),
                ("carol", "dave", None, None),
            ),
        )

    def test_optional_blocks_processed_in_order(self):
        result = self.model.query(
            "SELECT * WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z } ."
            " OPTIONAL { ?y email ?e } }"
        )
        self.assertEqual(result.variables, ("?x", "?y", "?z", "?e"))
        self.assertEqual(
            result.rows,
            (
                ("alice", "bob", "soccer", None),
                ("alice", "bob", "tennis", None),
                ("bob", "carol", "music", "c@example.com"),
                ("carol", "dave", None, None),
            ),
        )

    def test_chained_optional_depends_on_previous_optional_variable(self):
        # 第二个 OPTIONAL 引用第一个块的 ?z；?z 未绑定时整块无匹配
        result = self.model.query(
            "SELECT * WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z } ."
            " OPTIONAL { ?z label ?l } }"
        )
        self.assertEqual(
            result.rows,
            (
                ("alice", "bob", "soccer", None),
                ("alice", "bob", "tennis", None),
                ("bob", "carol", "music", None),
                ("carol", "dave", None, None),
            ),
        )

    def test_optional_with_derived_triples(self):
        model = query_model()
        # bob likes carol 是显式事实；carol 没有任何 likes
        result = model.query(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } }"
        )
        self.assertEqual(
            result.rows,
            (("alice", "bob", "carol"), ("bob", "carol", None)),
        )

    def test_optional_inner_join_filters_on_outer_binding(self):
        # 块内 ?y 已由外层绑定，只匹配以该 ?y 为主语的 email
        result = self.model.query(
            "SELECT ?y ?e WHERE { ?x knows ?y . OPTIONAL { ?y email ?e } }"
        )
        self.assertEqual(
            result.rows,
            (("bob", None), ("carol", "c@example.com"), ("dave", None)),
        )

    def test_optional_variable_can_be_explicit_projection(self):
        result = self.model.query(
            "SELECT ?z WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } }"
        )
        self.assertEqual(result.variables, ("?z",))
        # None 占位行经投影去重后只剩一个 None 行
        self.assertEqual(result.rows, ((None,), ("music",), ("soccer",), ("tennis",)))

    def test_none_sorts_before_strings(self):
        result = self.model.query(
            "SELECT ?z WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } }"
        )
        self.assertIsNone(result.rows[0][0])

    def test_star_variable_order_includes_optional_first_appearance(self):
        result = self.model.query(
            "SELECT * WHERE { OPTIONAL { ?a label ?b } ?x knows ?y ."
            " OPTIONAL { ?y likes ?z } }"
        )
        self.assertEqual(result.variables, ("?a", "?b", "?x", "?y", "?z"))

    def test_filter_bound_and_not_bound(self):
        bound = self.model.query(
            "SELECT ?y ?z WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z } . FILTER(BOUND(?z)) }"
        )
        self.assertEqual(
            bound.rows,
            (("bob", "soccer"), ("bob", "tennis"), ("carol", "music")),
        )
        not_bound = self.model.query(
            "SELECT ?y ?z WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z } . FILTER(!BOUND(?z)) }"
        )
        self.assertEqual(not_bound.rows, (("dave", None),))

    def test_filter_variable_equality_and_inequality(self):
        equal = self.model.query(
            "SELECT ?x ?y WHERE { ?x knows ?y . FILTER(?x = ?y) }"
        )
        self.assertEqual(equal.rows, ())
        not_equal = self.model.query(
            "SELECT ?x ?y WHERE { ?x knows ?y . FILTER(?x != ?y) }"
        )
        self.assertEqual(
            not_equal.rows,
            (("alice", "bob"), ("bob", "carol"), ("carol", "dave")),
        )

    def test_filter_string_literal_comparisons(self):
        prefix = "SELECT ?y WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } "
        self.assertEqual(
            self.model.query(prefix + ". FILTER(?z = \"tennis\") }").rows,
            (("bob",),),
        )
        self.assertEqual(
            self.model.query(prefix + ". FILTER(?z != \"tennis\") }").rows,
            (("bob",), ("carol",)),
        )
        self.assertEqual(
            self.model.query(
                "SELECT ?x WHERE { ?x knows ?y . FILTER(\"a\" = \"a\") }"
            ).rows,
            (("alice",), ("bob",), ("carol",)),
        )
        self.assertEqual(
            self.model.query(
                "SELECT ?x WHERE { ?x knows ?y . FILTER(\"a\" != \"a\") }"
            ).rows,
            (),
        )
        self.assertEqual(
            self.model.query(
                "SELECT ?y WHERE { ?x knows ?y ."
                " OPTIONAL { ?y likes ?z } . FILTER(\"tennis\" = ?z) }"
            ).rows,
            (("bob",),),
        )

    def test_filter_unbound_comparison_is_false_for_eq_and_ne(self):
        # ?z 在 dave 行未绑定：= 与 != 都为假，该行被过滤
        for op in ("=", "!="):
            result = self.model.query(
                f"SELECT ?y WHERE {{ ?x knows ?y ."
                f" OPTIONAL {{ ?y likes ?z }} . FILTER(?z {op} \"tennis\") }}"
            )
            self.assertNotIn(("dave",), result.rows)

    def test_multiple_filters_combined_with_logical_and(self):
        result = self.model.query(
            "SELECT ?z WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } ."
            " FILTER(BOUND(?z)) . FILTER(?z != \"tennis\") }"
        )
        # bob 的另一个取值 soccer 与 carol 的 music 保留
        self.assertEqual(result.rows, (("music",), ("soccer",)))

    def test_filter_before_optional(self):
        result = self.model.query(
            "SELECT ?y WHERE { ?x knows ?y . FILTER(?y = \"carol\") ."
            " OPTIONAL { ?y likes ?z } }"
        )
        self.assertEqual(result.rows, (("carol",),))

    def test_filter_clause_boundaries_do_not_require_dots(self):
        result = self.model.query(
            "SELECT ?y WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z }"
            " FILTER(BOUND(?z)) }"
        )
        # 按 ?y 投影去重：dave 因 ?z 未绑定被过滤
        self.assertEqual(result.rows, (("bob",), ("carol",)))

    def test_optional_filter_result_is_deduped_sorted_and_immutable(self):
        result = self.model.query(
            "SELECT ?z WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } }"
        )
        self.assertIsInstance(result.rows, tuple)
        self.assertTrue(all(isinstance(row, tuple) for row in result.rows))
        self.assertEqual(result.rows, tuple(sorted(result.rows, key=lambda r: (0, "") if r[0] is None else (1, r[0]))))
        with self.assertRaises(TypeError):
            result.rows[0] = ("x",)

    def test_query_with_optional_filter_is_repeatable(self):
        text = (
            "SELECT * WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z } . FILTER(BOUND(?x)) }"
        )
        first = self.model.query(text)
        for _ in range(3):
            self.assertEqual(self.model.query(text), first)

    def test_optional_filter_query_does_not_mutate_model(self):
        before = (
            self.model.explicit_triples,
            self.model.derived_triples,
            self.model.triples,
        )
        self.model.query(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z } ."
            " FILTER(!BOUND(?z)) }"
        )
        after = (
            self.model.explicit_triples,
            self.model.derived_triples,
            self.model.triples,
        )
        self.assertEqual(before, after)

    def test_optional_filter_does_not_change_other_model_behaviors(self):
        self.assertTrue(self.model.entails("bob", "likes", "tennis"))
        self.assertIsNone(self.model.source_rule("bob", "likes", "tennis"))
        self.assertEqual(
            self.model.query("SELECT ?x ?y WHERE { ?x knows ?y }").rows,
            (("alice", "bob"), ("bob", "carol"), ("carol", "dave")),
        )


class OptionalFilterSyntaxErrorTests(unittest.TestCase):
    def setUp(self):
        self.model = optional_model()

    def assertQueryError(self, text):
        with self.assertRaises(OntologyError) as ctx:
            self.model.query(text)
        message = str(ctx.exception)
        self.assertTrue(
            "字符位置" in message or "模式" in message,
            f"错误消息缺少字符位置或模式序号: {message}",
        )
        return message

    def test_nested_optional_rejected(self):
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y ."
            " OPTIONAL { OPTIONAL { ?y likes ?z } } }"
        )

    def test_filter_inside_optional_rejected(self):
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y ."
            " OPTIONAL { ?y likes ?z . FILTER(BOUND(?z)) } }"
        )

    def test_empty_optional_block_rejected(self):
        msg = self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL { } }"
        )
        self.assertIn("OPTIONAL", msg)

    def test_optional_missing_brace(self):
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL ?y likes ?z }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z }"
        )

    def test_optional_trailing_dot_is_accepted(self):
        # 块内尾点号与 WHERE 体内尾点号行为一致
        result = self.model.query(
            "SELECT * WHERE { ?x knows ?y . OPTIONAL { ?y likes ?z . } }"
        )
        self.assertEqual(
            result.rows,
            (
                ("alice", "bob", "soccer"),
                ("alice", "bob", "tennis"),
                ("bob", "carol", "music"),
                ("carol", "dave", None),
            ),
        )

    def test_filter_missing_or_empty_parens(self):
        self.assertQueryError("SELECT * WHERE { ?x knows ?y . FILTER }")
        self.assertQueryError("SELECT * WHERE { ?x knows ?y . FILTER( }")
        self.assertQueryError("SELECT * WHERE { ?x knows ?y . FILTER() }")
        self.assertQueryError("SELECT * WHERE { ?x knows ?y . FILTER(?x = ?y")
        self.assertQueryError("SELECT * WHERE { ?x knows ?y . FILTER(BOUND(?x) }")

    def test_unknown_filter_expressions(self):
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(?x > ?y) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(?x = bob) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(!?x) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(?x) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(BOUND) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(BOUND(?x ?y)) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(BOUND(?x) = 1) }"
        )
        self.assertQueryError(
            "SELECT * WHERE { ?x knows ?y . FILTER(!BOUND()) }"
        )

    def test_filter_only_body_is_empty_group(self):
        self.assertQueryError("SELECT * WHERE { FILTER(BOUND(?x)) }")

    def test_optional_keyword_as_constant_still_works(self):
        # 未跟 '{' 的 OPTIONAL 与未跟 '(' 的 FILTER 仍是普通常量名
        doc = make_doc(
            properties=["FILTER", "OPTIONAL"],
            triples=[
                {"subject": "alice", "predicate": "FILTER", "object": "v1"},
                {"subject": "alice", "predicate": "OPTIONAL", "object": "v2"},
            ],
        )
        model = parse(doc)
        self.assertEqual(
            model.query("SELECT ?v WHERE { ?s FILTER ?v }").rows, (("v1",),)
        )
        self.assertEqual(
            model.query("SELECT ?v WHERE { ?s OPTIONAL ?v }").rows, (("v2",),)
        )


