            {"subject": "carol", "predicate": "knows", "object": "dave"},
            {"subject": "bob", "predicate": "likes", "object": "tennis"},
            {"subject": "bob", "predicate": "likes", "object": "soccer"},
            {"subject": "carol", "predicate": "likes", "object": "music"},
