            " FILTER (BOUND(?o)) }"
        )
        self.assertEqual(
            result.rows,
            (
                ("alice", "bob"),
                ("bob", "carol"),
                ("bob", "soccer"),
                ("bob", "tennis"),
                ("carol", "dave"),
                ("carol", "music"),
            ),
        )

