            (
                ("alice", "soccer"),
                ("alice", "tennis"),
                ("bob", "music"),
                ("bob", "soccer"),
                ("bob", "tennis"),
                ("carol", "music"),
            ),
        )

    def test_branch_without_match_falls_back_to_other_branch(self):
